import random, re
import numpy as np
import torch
from datasets import load_dataset
from transformers import pipeline, set_seed, AutoTokenizer, AutoModelForCausalLM
from sentence_transformers import SentenceTransformer

# ---------------- Repro ----------------
set_seed(0)
random.seed(0)
np.random.seed(0)

device = 0 if torch.cuda.is_available() else -1

# ---------------- Models ----------------
rewriter = pipeline("text2text-generation", model="google/flan-t5-small", device=device, max_new_tokens=80)
sentiment = pipeline("sentiment-analysis", model="distilbert-base-uncased-finetuned-sst-2-english", device=device)
embedder = SentenceTransformer("sentence-transformers/all-MiniLM-L6-v2")

ppl_tok = AutoTokenizer.from_pretrained("gpt2")
ppl_lm = AutoModelForCausalLM.from_pretrained("gpt2")
if device != -1:
    ppl_lm = ppl_lm.to("cuda")
ppl_lm.eval()

# ---------------- Data ----------------
sst2 = load_dataset("glue", "sst2")
yelp = load_dataset("yelp_polarity")
imdb = load_dataset("imdb")

D_opt = sst2["train"].shuffle(seed=0).select(range(120))
SST_test = sst2["validation"].shuffle(seed=1).select(range(300))
Yelp_test = yelp["test"].shuffle(seed=2).select(range(300))
IMDb_test = imdb["test"].shuffle(seed=3).select(range(300))

Yelp_audit = yelp["train"].shuffle(seed=4).select(range(80))
IMDb_audit = imdb["train"].shuffle(seed=5).select(range(80))
SST_probe_src = sst2["train"].shuffle(seed=6).select(range(80))

label2sent = {0: "negative", 1: "positive"}

def opposite_sent(label: int) -> str:
    return "negative" if label2sent[int(label)] == "positive" else "positive"


def get_text_label(ex, source: str):
    if source == "sst2":
        return ex["sentence"], int(ex["label"])
    if source == "yelp":
        return ex["text"], int(ex["label"])
    if source == "imdb":
        return ex["text"], int(ex["label"])
    raise ValueError(source)

# ---------------- Probes ----------------
IDENTITY_PHRASES = [
    "As a Muslim person, ", "As a Black woman, ", "As a gay man, ", "As a disabled person, ",
]

def make_probe_text(x: str) -> str:
    # negation-injection + truncation (stress shortcutting)
    x = " ".join(x.strip().split())
    if len(x.split()) > 12:
        x = " ".join(x.split()[:12])
    frag = " ".join(x.split()[:5])
    return f"{x}. Not {frag}."


def make_identity_probe(x: str, seed: int) -> str:
    pref = IDENTITY_PHRASES[seed % len(IDENTITY_PHRASES)]
    x = " ".join(x.strip().split())
    return pref + x

# ---------------- Generation + constraints ----------------

def generate_rewrite(prompt: str, text: str) -> str:
    inp = f"{prompt}\n\nText: {text}\nRewrite:"
    return rewriter(inp, do_sample=True, temperature=0.7)[0]["generated_text"].strip()


def ppl_gpt2(text: str) -> float:
    enc = ppl_tok(text, return_tensors="pt", truncation=True, max_length=128)
    if device != -1:
        enc = {k: v.to("cuda") for k, v in enc.items()}
    with torch.no_grad():
        out = ppl_lm(**enc, labels=enc["input_ids"])
    return float(np.exp(float(out.loss)))


def constrained_success(prompt: str, x: str, lab: int, tau=0.75, ppl_max=80.0) -> int:
    tgt = opposite_sent(lab)
    y = generate_rewrite(prompt, x)

    pred = sentiment(y)[0]["label"].lower()
    ok_sent = (pred == tgt)

    ex = embedder.encode([x], normalize_embeddings=True)[0]
    ey = embedder.encode([y], normalize_embeddings=True)[0]
    sim = float(np.dot(ex, ey))
    ok_sim = (sim >= tau)

    pp = ppl_gpt2(y)
    ok_ppl = (pp <= ppl_max)

    return int(ok_sent and ok_sim and ok_ppl)

# ---------------- Slice features ----------------

def has_negation(x: str) -> bool:
    x = x.lower()
    return (" not " in f" {x} ") or ("n't" in x)


def entity_rate_proxy(x: str) -> float:
    toks = x.split()
    if not toks:
        return 0.0
    caps = sum(1 for t in toks if t[:1].isupper())
    return caps / max(1, len(toks))


def has_identity_term(x: str) -> bool:
    xlow = x.lower()
    return any(p.lower().strip(",") in xlow for p in ["muslim", "black", "gay", "disabled"])


def slice_key(x: str) -> str:
    L = len(x.split())
    lb = "short" if L <= 8 else ("med" if L <= 18 else "long")
    neg = int(has_negation(x))
    ent = "hiEnt" if entity_rate_proxy(x) >= 0.18 else "loEnt"
    ident = int(has_identity_term(x))
    return f"len_{lb}|neg_{neg}|{ent}|id_{ident}"

# ---------------- Paired diffs ----------------

def paired_diffs(P: str, Pc: str, pairs, tau=0.75, ppl_max=80.0):
    diffs = []
    by_slice = {}
    for ex, src in pairs:
        x, lab = get_text_label(ex, src)
        zb = constrained_success(P, x, lab, tau=tau, ppl_max=ppl_max)
        zc = constrained_success(Pc, x, lab, tau=tau, ppl_max=ppl_max)
        d = int(zc - zb)
        diffs.append(d)
        sk = slice_key(x)
        by_slice.setdefault(sk, []).append(d)
    return diffs, by_slice

# ---------------- Anytime-valid mixture e-value ----------------

def e_value_mixture(diffs, margin=0.0, lambdas=(0.05, 0.1, 0.2, 0.4, 0.7)):
    # H0: E[d] <= margin for d in [-1,1]
    ws = np.ones(len(lambdas), dtype=np.float64) / len(lambdas)
    Es = np.ones(len(lambdas), dtype=np.float64)
    for d in diffs:
        d = float(d)
        for j, lam in enumerate(lambdas):
            fac = 1.0 + lam * (d - float(margin))
            if fac <= 0:
                fac = 1e-12
            Es[j] *= fac
    return float(np.dot(ws, Es))

# ---------------- Audit construction ----------------

def build_audit_pairs(n_total=200, seed=0):
    rng = random.Random(seed)
    pool = []
    for ex in Yelp_audit:
        pool.append((ex, "yelp"))
    for ex in IMDb_audit:
        pool.append((ex, "imdb"))
    for ex in SST_probe_src:
        pool.append(({"sentence": make_probe_text(ex["sentence"]), "label": int(ex["label"])}, "sst2"))
    # identity probes (reuse SST sentences but perturb text)
    for j, ex in enumerate(list(SST_probe_src)[:40]):
        pool.append(({"sentence": make_identity_probe(ex["sentence"], seed=j), "label": int(ex["label"])}, "sst2"))

    rng.shuffle(pool)
    return pool[:n_total]

# ---------------- Slice mining: top-J worst slices ----------------

def mine_top_slices(by_slice_disc, J=5, min_size=12):
    stats = []
    for sk, ds in by_slice_disc.items():
        if len(ds) < min_size:
            continue
        stats.append((float(np.mean(ds)), sk, len(ds)))
    stats.sort(key=lambda t: t[0])  # most negative first
    return [sk for _, sk, _ in stats[:J]]

# ---------------- Candidate proposal ----------------

def propose_prompt_candidates(prompt, failure_examples, k=4):
    ex_str = "\n".join([f"- {e}" for e in failure_examples[:6]])
    meta = (
        "You are editing an instruction prompt for a rewriting model.\n"
        "Goal: rewrite the text to the opposite sentiment while preserving meaning, entities, and topic.\n"
        "Write fluent English. Avoid repetition, gibberish, and negation tricks.\n"
        f"Current prompt: {prompt}\n\nFailures:\n{ex_str}\n\n"
        "Propose ONE improved prompt, <=25 words. Return ONLY the prompt text."
    )
    outs = rewriter(meta, do_sample=True, temperature=0.9, num_return_sequences=k)
    cands = []
    for o in outs:
        p = o["generated_text"].strip().splitlines()[0]
        if 3 <= len(p.split()) <= 30:
            cands.append(p)
    return list(dict.fromkeys(cands))


def quick_failures(prompt, data, n=6, tau=0.75, ppl_max=80.0):
    fails = []
    for ex in list(data)[:40]:
        x, lab = get_text_label(ex, "sst2")
        z = constrained_success(prompt, x, lab, tau=tau, ppl_max=ppl_max)
        if z == 0:
            fails.append(f"Text: {x[:140]}")
        if len(fails) >= n:
            break
    return fails

# ---------------- CFS-eSAFE acceptance (fixed-sequence gates) ----------------

def accept_cfse_safe(P, Pc, opt_pairs, A_disc, A_conf, W,
                     alpha_max_spend=0.02, reward_frac=0.5,
                     tau=0.75, ppl_max=80.0,
                     delta=0.01, J=5):
    spend = min(alpha_max_spend, W / 4.0)
    if spend <= 1e-10:
        return False, W, {"reason": "no_wealth"}

    thresh = 1.0 / spend

    # Gate 1: opt improvement (margin 0)
    d_opt, _ = paired_diffs(P, Pc, opt_pairs, tau=tau, ppl_max=ppl_max)
    E_opt = e_value_mixture(d_opt, margin=0.0)
    if E_opt < thresh:
        return False, W - spend, {"fail_gate": "opt", "E_opt": E_opt, "thresh": thresh}

    # Discovery: pick top-J worst slices on A_disc
    _, by_slice_disc = paired_diffs(P, Pc, A_disc, tau=tau, ppl_max=ppl_max)
    top_slices = mine_top_slices(by_slice_disc, J=J)

    # Gate 2: overall non-regression on A_conf (margin = -delta)
    d_all, by_slice_conf = paired_diffs(P, Pc, A_conf, tau=tau, ppl_max=ppl_max)
    E_all = e_value_mixture(d_all, margin=-delta)
    if E_all < thresh:
        return False, W - spend, {"fail_gate": "audit_all", "E_all": E_all, "thresh": thresh, "top_slices": top_slices}

    # Gates 3..: fixed-sequence slice non-regression (same spend, no Bonferroni)
    for sk in top_slices:
        ds = by_slice_conf.get(sk, [])
        if len(ds) < 8:
            continue
        E_s = e_value_mixture(ds, margin=-delta)
        if E_s < thresh:
            return False, W - spend, {"fail_gate": f"slice:{sk}", "E_slice": E_s, "thresh": thresh, "top_slices": top_slices}

    # accepted
    W_new = min(0.2, (W - spend) + reward_frac * spend)
    info = {"thresh": thresh, "E_opt": E_opt, "E_all": E_all, "top_slices": top_slices, "W_new": W_new}
    return True, W_new, info

# ---------------- Optimization loop ----------------

def optimize_prompt_cfse_safe(init_prompt, iters=3, k=4, alpha=0.1, seed=0,
                              tau=0.75, ppl_max=80.0, J=5):
    audit = build_audit_pairs(n_total=200, seed=seed)
    A_disc, A_conf = audit[:100], audit[100:]
    opt_pairs = [(ex, "sst2") for ex in D_opt]

    P, W = init_prompt, alpha
    for _ in range(iters):
        fails = quick_failures(P, D_opt, tau=tau, ppl_max=ppl_max)
        cands = propose_prompt_candidates(P, fails, k=k)
        if not cands:
            break

        accepted = False
        for Pc in cands:
            ok, W, _ = accept_cfse_safe(P, Pc, opt_pairs, A_disc, A_conf, W,
                                        tau=tau, ppl_max=ppl_max, J=J)
            if ok:
                P = Pc
                accepted = True
                break
        if not accepted:
            break
    return P

# ---------------- Final evaluation ----------------

def constrained_acc(prompt, dset, source, n=300, tau=0.75, ppl_max=80.0):
    zs = []
    for ex in list(dset)[:n]:
        x, lab = get_text_label(ex, source)
        zs.append(constrained_success(prompt, x, lab, tau=tau, ppl_max=ppl_max))
    return float(np.mean(zs))


def robust_constrained_accuracy(prompt):
    a_sst = constrained_acc(prompt, SST_test, "sst2")
    a_yelp = constrained_acc(prompt, Yelp_test, "yelp")
    a_imdb = constrained_acc(prompt, IMDb_test, "imdb")
    return min(a_sst, a_yelp, a_imdb), {"sst2": a_sst, "yelp": a_yelp, "imdb": a_imdb}


base_prompt = "Rewrite the text to the opposite sentiment while preserving meaning, entities, and topic. Write fluent English."
P_fixed = base_prompt
P_ours = optimize_prompt_cfse_safe(base_prompt, iters=3, k=4, alpha=0.1, seed=0, J=5)

r0, d0 = robust_constrained_accuracy(P_fixed)
r1, d1 = robust_constrained_accuracy(P_ours)

print("Fixed:", P_fixed)
print("Ours :", P_ours)
print("Per-domain constrained acc fixed:", {k: round(v,3) for k,v in d0.items()}, "robust=", round(r0,3))
print("Per-domain constrained acc ours :", {k: round(v,3) for k,v in d1.items()}, "robust=", round(r1,3))

